import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"九辩","description":"","frontmatter":{"title":"九辩","date":"2026-11-24T00:00:00.000Z","seq":26,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"宋玉","source_book":"楚辞","prev":{"text":"渔父","link":"/blogs/楚辞/渔父.html"},"next":{"text":"招魂","link":"/blogs/楚辞/招魂.html"}},"headers":[],"relativePath":"blogs/楚辞/九辩.md","filePath":"blogs/楚辞/九辩.md"}'),o={name:"blogs/楚辞/九辩.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="九辩" tabindex="-1">九辩 <a class="header-anchor" href="#九辩" aria-label="Permalink to &quot;九辩&quot;">​</a></h1><p class="poem-meta">先秦 · 宋玉　·　九辩</p><div class="poem"><p class="poem-stanza">悲哉，秋之为气也！萧瑟兮草木摇落而变衰。</p><p class="poem-stanza">憭栗兮若在远行，登山临水兮送将归。</p><p class="poem-stanza">泬漻兮天高而气清，寂寥兮收潦而水清。</p><p class="poem-stanza">憯悽增欷兮，薄寒之中人，怆怳懭悢兮，去故而就新。</p><p class="poem-stanza">坎廪兮贫士失职而志不平，廓落兮羁旅而无友生，惆怅兮而私自怜！</p><p class="poem-stanza">燕翩翩其辞归兮，蝉寂漠而无声。</p><p class="poem-stanza">雁廱廱而南游兮，鹍鸡啁哳而悲鸣。</p><p class="poem-stanza">独申旦而不寐兮，哀蟋蟀之宵征。</p><p class="poem-stanza">时亹亹而过中兮，蹇淹留而无成。</p><p class="poem-stanza">悲忧穷戚兮独处廓，有美一人兮心不绎。</p><p class="poem-stanza">去乡离家兮来远客，超逍遥兮今焉薄！</p><p class="poem-stanza">专思君兮不可化，君不知兮可奈何！</p><p class="poem-stanza">蓄怨兮积思，心烦憺兮忘食事。</p><p class="poem-stanza">原一见兮道余意，君之心兮与余异。</p><p class="poem-stanza">车既驾兮朅而归，不得见兮心伤悲。</p><p class="poem-stanza">倚结軨兮长太息，涕潺湲兮下霑轼。</p><p class="poem-stanza">忼慨绝兮不得，中瞀乱兮迷惑。</p><p class="poem-stanza">私自怜兮何极？</p><p class="poem-stanza">心怦怦兮谅直。</p><p class="poem-stanza">皇天平分四时兮，窃独悲此凛秋。</p><p class="poem-stanza">白露既下百草兮，奄离披此梧楸。</p><p class="poem-stanza">去白日之昭昭兮，袭长夜之悠悠。</p><p class="poem-stanza">离芳蔼之方壮兮，余萎约而悲愁。</p><p class="poem-stanza">秋既先戒以白露兮，冬又申之以严霜。</p><p class="poem-stanza">收恢台之孟夏兮，然欿傺而沉藏。</p><p class="poem-stanza">叶菸邑而无色兮，枝烦挐而交横。</p><p class="poem-stanza">颜淫溢而将罢兮，柯仿佛而萎黄。</p><p class="poem-stanza">萷櫹椮之可哀兮，形销铄而瘀伤。</p><p class="poem-stanza">惟其纷糅而将落兮，恨其失时而无当。</p><p class="poem-stanza">揽騑辔而下节兮，聊逍遥以相佯。</p><p class="poem-stanza">岁忽忽而遒尽兮，恐余寿之弗将。</p><p class="poem-stanza">悼余生之不时兮，逢此世之俇攘。</p><p class="poem-stanza">澹容与而独倚兮，蟋蟀鸣此西堂。</p><p class="poem-stanza">心怵惕而震荡兮，何所忧之多方。</p><p class="poem-stanza">卬明月而太息兮，步列星而极明。</p><p class="poem-stanza">窃悲夫蕙华之曾敷兮，纷旖旎乎都房。</p><p class="poem-stanza">何曾华之无实兮，从风雨而飞飏！</p><p class="poem-stanza">以为君独服此蕙兮，羌无以异于众芳。</p><p class="poem-stanza">闵奇思之不通兮，将去君而高翔。</p><p class="poem-stanza">心闵怜之惨悽兮，愿一见而有明。</p><p class="poem-stanza">重无怨而生离兮，中结轸而增伤。</p><p class="poem-stanza">岂不郁陶而思君兮？</p><p class="poem-stanza">君之门以九重！猛犬狺狺而迎吠兮，关梁闭而不通。</p><p class="poem-stanza">皇天淫溢而秋霖兮，后土何时而得漧？</p><p class="poem-stanza">塊独守此无泽兮，仰浮云而永叹！何时俗之工巧兮？</p><p class="poem-stanza">背绳墨而改错！郤骐骥而不乘兮，策驽骀而取路。</p><p class="poem-stanza">当世岂无骐骥兮，诚莫之能善御。</p><p class="poem-stanza">见执辔者非其人兮，故駶跳而远去。</p><p class="poem-stanza">凫雁皆唼夫梁藻兮，凤愈飘翔而高举。</p><p class="poem-stanza">圜凿而方枘兮，吾固知其鉏铻而难入。</p><p class="poem-stanza">众鸟皆有所登棲兮，凤独遑遑而无所集。</p><p class="poem-stanza">原衔枚而无言兮，尝被君之渥洽。</p><p class="poem-stanza">太公九十乃显荣兮，诚未遇其匹合。</p><p class="poem-stanza">谓骐骥兮安归？</p><p class="poem-stanza">谓凤皇兮安棲？</p><p class="poem-stanza">变古易俗兮世衰，今之相者兮举肥。</p><p class="poem-stanza">骐骥伏匿而不见兮，凤皇高飞而不下。</p><p class="poem-stanza">鸟兽犹知怀德兮，何云贤士之不处？</p><p class="poem-stanza">骥不骤进而求服兮，凤亦不贪餧而妄食。</p><p class="poem-stanza">君弃远而不察兮，虽原忠其焉得？</p><p class="poem-stanza">欲寂漠而绝端兮，窃不敢忘初之厚德。</p><p class="poem-stanza">独悲愁其伤人兮，冯郁郁其何极？</p><p class="poem-stanza">霜露惨悽而交下兮，心尚幸其弗济。</p><p class="poem-stanza">霰雪雰糅其增加兮，乃知遭命之将至。</p><p class="poem-stanza">原徼幸而有待兮，泊莽莽与野草同死。</p><p class="poem-stanza">原自往而径游兮，路壅绝而不通。</p><p class="poem-stanza">欲循道而平驱兮，又未知其所从。</p><p class="poem-stanza">然中路而迷惑兮，自压桉而学诵。</p><p class="poem-stanza">性愚陋以褊浅兮，信未达乎从容。</p><p class="poem-stanza">窃美申包胥之气盛兮，恐时世之不固。</p><p class="poem-stanza">何时俗之工巧兮？</p><p class="poem-stanza">灭规矩而改凿！独耿介而不随兮，原慕先圣之遗教。</p><p class="poem-stanza">处浊世而显荣兮，非余心之所乐。</p><p class="poem-stanza">与其无义而有名兮，宁穷处而守高。</p><p class="poem-stanza">食不媮而为饱兮，衣不苟而为温。</p><p class="poem-stanza">窃慕诗人之遗风兮，原讬志乎素餐。</p><p class="poem-stanza">蹇充倔而无端兮，泊莽莽而无垠。</p><p class="poem-stanza">无衣裘以御冬兮，恐溘死不得见乎阳春。</p><p class="poem-stanza">靓杪秋之遥夜兮，心缭悷而有哀。</p><p class="poem-stanza">春秋逴逴而日高兮，然惆怅而自悲。</p><p class="poem-stanza">四时递来而卒岁兮，阴阳不可与俪偕。</p><p class="poem-stanza">白日晼晚其将入兮，明月销铄而减毁。</p><p class="poem-stanza">岁忽忽而遒尽兮，老冉冉而愈弛。</p><p class="poem-stanza">心摇悦而日幸兮，然怊怅而无冀。</p><p class="poem-stanza">中憯恻之悽怆兮，长太息而增欷。</p><p class="poem-stanza">年洋洋以日往兮，老嵺廓而无处。</p><p class="poem-stanza">事亹亹而觊进兮，蹇淹留而踌躇。</p><p class="poem-stanza">何氾滥之浮云兮？</p><p class="poem-stanza">猋壅蔽此明月。</p><p class="poem-stanza">忠昭昭而原见兮，然霠曀而莫达。</p><p class="poem-stanza">原皓日之显行兮，云蒙蒙而蔽之。</p><p class="poem-stanza">窃不自聊而原忠兮，或黕点而汙之。</p><p class="poem-stanza">尧舜之抗行兮，瞭冥冥而薄天。</p><p class="poem-stanza">何险巇之嫉妒兮？</p><p class="poem-stanza">被以不慈之伪名。</p><p class="poem-stanza">彼日月之照明兮，尚黯黮而有瑕。</p><p class="poem-stanza">何况一国之事兮，亦多端而胶加。</p><p class="poem-stanza">被荷裯之晏晏兮，然潢洋而不可带。</p><p class="poem-stanza">既骄美而伐武兮，负左右之耿介。</p><p class="poem-stanza">憎愠惀之修美兮，好夫人之慷慨。</p><p class="poem-stanza">众踥蹀而日进兮，美超远而逾迈。</p><p class="poem-stanza">农夫辍耕而容与兮，恐田野之芜秽。</p><p class="poem-stanza">事緜緜而多私兮，窃悼後之危败。</p><p class="poem-stanza">世雷同而炫曜兮，何毁誉之昧昧！</p><p class="poem-stanza">今修饰而窥镜兮，後尚可以竄藏。</p><p class="poem-stanza">愿寄言夫流星兮，羌倏忽而难当。</p><p class="poem-stanza">卒壅蔽此浮云，下暗漠而无光。</p><p class="poem-stanza">尧舜皆有所举任兮，故高枕而自适。</p><p class="poem-stanza">谅无怨于天下兮，心焉取此怵惕？</p><p class="poem-stanza">乘骐骥之浏浏兮，驭安用夫强策？</p><p class="poem-stanza">谅城郭之不足恃兮，虽重介之何益？</p><p class="poem-stanza">邅翼翼而无终兮，忳惛惛而愁约。</p><p class="poem-stanza">生天地之若过兮，功不成而无嶜。</p><p class="poem-stanza">原沉滞而不见兮，尚欲布名乎天下。</p><p class="poem-stanza">然潢洋而不遇兮，直怐愗而自苦。</p><p class="poem-stanza">莽洋洋而无极兮，忽翱翔之焉薄？</p><p class="poem-stanza">国有骥而不知乘兮，焉皇皇而更索？</p><p class="poem-stanza">宁戚讴于车下兮，桓公闻而知之。</p><p class="poem-stanza">无伯乐之相善兮，今谁使乎誉之？</p><p class="poem-stanza">罔流涕以聊虑兮，惟著意而得之。</p><p class="poem-stanza">纷纯纯之愿忠兮，妒被离而鄣之。</p><p class="poem-stanza">原赐不肖之躯而别离兮，放游志乎云中。</p><p class="poem-stanza">乘精气之抟抟兮，骛诸神之湛湛。</p><p class="poem-stanza">骖白霓之習習兮，历群灵之丰丰。</p><p class="poem-stanza">左硃雀之茇茇兮，右苍龙之躣躣。</p><p class="poem-stanza">属雷师之阗阗兮，通飞廉之衙衙。</p><p class="poem-stanza">前轻辌之锵锵兮，后辎乘之从从。</p><p class="poem-stanza">载云旗之委蛇兮，扈屯骑之容容。</p><p class="poem-stanza">计专专之不可化兮，原遂推而为臧。</p><p class="poem-stanza">赖皇天之厚德兮，还及君之无恙！</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
